const shadowSamples = `-- name: ShadowSamples :many
SELECT transaction_id, evaluation, agent_id, operation, original_decision, original_reason, shadow_decision, shadow_reason,
    category, limitation, created_at
FROM (SELECT s.org_id, s.rollout_id, s.transaction_id, s.evaluation, s.agent_id, s.operation, s.original_decision, s.original_reason, s.shadow_decision, s.shadow_reason, s.category, s.limitation, s.created_at, row_number() OVER (PARTITION BY s.category ORDER BY s.created_at DESC, s.transaction_id DESC) AS rn
      FROM pc.policy_shadow_results s
      WHERE s.org_id = $1 AND s.rollout_id = $2 AND s.category <> 'UNCHANGED') x
WHERE x.rn <= $3::bigint
ORDER BY category, created_at DESC
`

type ShadowSamplesRow struct {
	TransactionID    ids.UUID
	Evaluation       int32
	AgentID          ids.UUID
	Operation        string
	OriginalDecision string
	OriginalReason   string
	ShadowDecision   *string
	ShadowReason     *string
	Category         string
	Limitation       *string
	CreatedAt        time.Time
}

// The newest results of each changed category: ids, decisions and reasons
// only (HR-237).
func (q *Queries) ShadowSamples(ctx context.Context, orgID ids.OrgID, rolloutID ids.UUID, perCategory int64) ([]ShadowSamplesRow, error) {
	rows, err := q.db.Query(ctx, shadowSamples, orgID, rolloutID, perCategory)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ShadowSamplesRow{}
	for rows.Next() {
		var i ShadowSamplesRow
		if err := rows.Scan(
			&i.TransactionID,
			&i.Evaluation,
			&i.AgentID,
			&i.Operation,
			&i.OriginalDecision,
			&i.OriginalReason,
			&i.ShadowDecision,
			&i.ShadowReason,
			&i.Category,
			&i.Limitation,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
